contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), address(this), address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test entry; takes all params needed to call initialize
    function run(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties
    ) public payable {
        require(true);

        // First call: attempt to initialize. Capture whether it reverted.
        bool firstReverted;
        c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstReverted = true;
        } else {
            firstReverted = false;
        }

        // Read initialized after first attempt.
        bool initializedAfterFirst = c.initialized(); if (__ESBMC_reverted()) return;

        // Second call: attempt to initialize again with the same inputs. Capture whether it reverted.
        bool secondReverted;
        c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondReverted = true;
        } else {
            secondReverted = false;
        }

        // Read initialized after second attempt.
        bool initializedAfterSecond = c.initialized(); if (__ESBMC_reverted()) return;

        // General rule to assert:
        // - If the first initialize call reverted, then initialized must remain false and the second call may or may not revert
        // - If the first initialize call succeeded, then initialized must be true, and the second call must revert (cannot succeed twice)
        // This enforces initialize is a one-time transition from false->true.
        assert(
            (
                firstReverted && initializedAfterFirst == false
            ) || (
                !firstReverted && initializedAfterFirst == true && secondReverted && initializedAfterSecond == true
            )
        );
    }

    receive() external payable {}
}

